face.layout_source:
// family.face: the panel for every graph in tap/examples that has no .face of its own.
//
// A graph's panel is `<graph>.face` beside its source when that exists, else
// the nearest family.face going up the tree.  Every pin in declaration
// order, beside the visualizer.

// Meters keep their full names here, so they need more room than a bar's own width.
bar { w: 76; }

face {
  row(gap = 10) {
    box "Controls" (wrap = 560) { * }
    viz(grow = 1, w = 240)
  }
}
